// Reference solution
function storageRisk(place) {
  if (place === 'localStorage') return 'XSS';
  if (place === 'plain-cookie') return 'XSS_AND_CSRF';
  if (place === 'httponly-cookie') return 'CSRF';
  if (place === 'memory') return 'LOST_ON_REFRESH';
  return 'UNKNOWN';
}
